import styled from 'styled-components';
import { useState } from 'react';

const AlbumContainer = styled.div`
  display: flex;
  flex-direction: column;
  padding: 20px;
`;

const AlbumItem = styled.div`
  background-color: #f5f5f5;
  padding: 20px;
  margin-bottom: 10px;
  display: flex;
  justify-content: space-between;
  border-radius: 4px;
  border: 1px solid #e0e0e0;
`;

const AlbumTitle = styled.p`
  font-weight: bold;
  margin: 0;
`;

const Button = styled.button`
  background-color: #1976d2;
  color: white;
  padding: 10px 20px;
  font-size: 16px;
  border: 2px solid #115293;
  border-radius: 4px;
  cursor: pointer;

  &:hover {
    background-color: #115293;
  }
`;

const LinkButton = styled.button`
  background-color: #1976d2;
  color: white;
  padding: 10px 20px;
  font-size: 16px;
  border: 2px solid #115293;
  border-radius: 4px;
  cursor: pointer;
  margin-left: 10px;

  &:hover {
    background-color: #115293;
  }

  &:disabled {
    background-color: gray;
    cursor: not-allowed;
  }
`;

function AlbumList({ albums, onSave }) {
  const [youtubeUrl, setYoutubeUrl] = useState({});
  const [loading, setLoading] = useState({}); // Track loading state

  const handleListen = async (title, artist) => {
    setLoading((prevState) => ({
      ...prevState,
      [`${title}-${artist}`]: true
    }));
    try {
      const response = await fetch(`/youtube-search?title=${encodeURIComponent(title)}&artist=${encodeURIComponent(artist)}`);
      const data = await response.json();
      if (data.url) {
        setYoutubeUrl((prevState) => ({
          ...prevState,
          [`${title}-${artist}`]: data.url
        }));
      }
    } catch (error) {
      console.error('Error fetching YouTube link:', error);
    }
    setLoading((prevState) => ({
      ...prevState,
      [`${title}-${artist}`]: false
    }));
  };

  if (albums.length === 0) {
    return <p>No recommendations available for this mood.</p>;
  }

  return (
    <AlbumContainer>
      <h2>Recommended Albums</h2>
      {albums.map((album, index) => (
        <AlbumItem key={index}>
          <div>
            <AlbumTitle>{album.title}</AlbumTitle>
            <p>by {album.artist}</p>
          </div>
          <div>
            <Button onClick={() => onSave(album)}>Tag for Later</Button>
            <LinkButton
              disabled={loading[`${album.title}-${album.artist}`]} // Disable only when loading
              onClick={() => handleListen(album.title, album.artist)}
            >
              {loading[`${album.title}-${album.artist}`]
                ? 'Loading...'
                : youtubeUrl[`${album.title}-${album.artist}`]
                ? <a href={youtubeUrl[`${album.title}-${album.artist}`]} target="_blank" rel="noopener noreferrer" style={{ color: 'white', textDecoration: 'none' }}>Listen</a>
                : 'Listen'}
            </LinkButton>
          </div>
        </AlbumItem>
      ))}
    </AlbumContainer>
  );
}

export default AlbumList;
